package prometheus

import (
	"github.com/timescale/promscale/pkg/prompb"
	"github.com/timescale/tsbs/cmd/tsbs_load_prometheus/adapter/noop"
	"net/http"
	"net/http/httptest"
	"net/url"
	"sync"
	"testing"
)

func TestPrometheusLoader(t *testing.T) {
	adapter := noop.Adapter{}
	server := httptest.NewServer(http.HandlerFunc(adapter.Handler))
	serverURL, err := url.Parse(server.URL)
	if err != nil {
		t.Fatal(err)
	}
	pb := Benchmark{
		adapterWriteUrl: serverURL.String(),
		batchPool:       &sync.Pool{},
	}
	pp := pb.GetProcessor().(*Processor)
	batch := &Batch{series: []prompb.TimeSeries{{}}}
	samples, _ := pp.ProcessBatch(batch, true)
	if samples != 1 {
		t.Error("wrong number of samples")
	}
	if adapter.SampleCounter != samples {
		t.Error("wrong number of samples processed")
	}
}

package prometheus

import (
	"github.com/timescale/promscale/pkg/prompb"
	"github.com/timescale/tsbs/pkg/data"
	"reflect"
	"testing"
	"time"
)

func TestTimeSeriesIterator(t *testing.T) {
	now := time.Now()
	emptyPoint := data.NewPoint()
	emptyPoint.SetTimestamp(&now)

	oneField := data.NewPoint()
	oneField.AppendTag([]byte("tag"), "tag")
	oneField.AppendField([]byte("m1"), float64(1))
	oneField.SetTimestamp(&now)

	twoFields := data.NewPoint()
	twoFields.AppendTag([]byte("tag"), "tag")
	twoFields.AppendField([]byte("m1"), float64(1))
	twoFields.AppendField([]byte("m2"), float64(2))
	twoFields.SetTimestamp(&now)

	cases := []struct {
		desc string
		set  *data.Point
	}{
		{
			desc: "No fields -> no time series",
			set:  emptyPoint,
		}, {
			desc: "One field one time series",
			set:  oneField,
		}, {
			desc: "Two fields two time series",
			set:  twoFields,
		},
	}

	for _, tc := range cases {
		t.Run(tc.desc, func(t *testing.T) {
			iter := timeSeriesIterator{}
			if iter.generatedSeries != nil || iter.currentInd != 0 {
				t.Errorf("unexpected initial iterator state; expected series: nil, currentInd: 0;"+
					" got: %v and %d", iter.generatedSeries, iter.currentInd)
				return
			}
			inputPoint := tc.set
			err := iter.Set(inputPoint)
			if err != nil {
				t.Error(err)
			}
			var generated []*prompb.TimeSeries
			for iter.HasNext() {
				generated = append(generated, iter.Next())
			}
			fieldKeys := inputPoint.FieldKeys()
			numExpectedTimeSeries := len(fieldKeys)
			if len(generated) != numExpectedTimeSeries {
				t.Errorf("expected time series for each field (total %d) got: %d",
					numExpectedTimeSeries, len(generated),
				)
			}

			for i, ts := range generated {
				if ts.Samples[0].Value != inputPoint.GetFieldValue(fieldKeys[i]) {
					t.Errorf("unexpected value in time-series; exp: %f; got: %f",
						inputPoint.GetFieldValue(fieldKeys[i]), ts.Samples[0].Value,
					)
				}
				for _, label := range ts.Labels {
					if label.Name == "__name__" {
						if label.Value != string(fieldKeys[i]) {
							t.Errorf("unexpected name for time-series: exp: %s; got %s",
								string(fieldKeys[i]), label.Value,
							)
						}
						continue
					}
					tagValue := inputPoint.GetTagValue([]byte(label.Name))
					if label.Value != tagValue.(string) {
						t.Errorf("unexpected tag in time-series; exp %s; got: %s",
							label.Value, tagValue,
						)
					}
				}
			}
			// check if properly reset after some generating has been done
			err = iter.Set(inputPoint)
			if err != nil {
				t.Error(err)
			}
			if len(iter.generatedSeries) != numExpectedTimeSeries {
				t.Errorf("after Set, iterator had unexpected generatedSeries len."+
					"Expected %d; got %d", len(iter.generatedSeries), numExpectedTimeSeries)
			}
			if iter.currentInd != 0 {
				t.Errorf("after Set, iterator currentInd not reset to 0; got: %d", iter.currentInd)
			}
		})
	}
}

func TestTimeSeriesIteratorMultipleSets(t *testing.T) {
	now := time.Now()
	emptyPoint := data.NewPoint()
	emptyPoint.SetTimestamp(&now)

	point := data.NewPoint()
	point.AppendTag([]byte("tag"), "tag")
	point.AppendField([]byte("m1"), float64(1))
	point.SetTimestamp(&now)
	promPoint := &prompb.TimeSeries{
		Labels:  []prompb.Label{{Name: "__name__", Value: "m1"}, {Name: "tag", Value: "tag"}},
		Samples: []prompb.Sample{{Timestamp: point.TimestampInUnixMs(), Value: float64(1)}},
	}

	futureTime := time.Now().AddDate(1, 0, 0).UnixNano() / 1000000
	promPointInFuture1 := &prompb.TimeSeries{
		Labels:  []prompb.Label{{Name: "__name__", Value: "m1"}, {Name: "tag", Value: "tag"}},
		Samples: []prompb.Sample{{Timestamp: futureTime + 1, Value: float64(1)}},
	}
	promPointInFuture2 := &prompb.TimeSeries{
		Labels:  []prompb.Label{{Name: "__name__", Value: "m1"}, {Name: "tag", Value: "tag"}},
		Samples: []prompb.Sample{{Timestamp: futureTime + 2, Value: float64(1)}},
	}
	cases := []struct {
		desc         string
		pointToSet   *data.Point
		useCurrentTs bool
		lastTsUsed   int64
		expect1      []*prompb.TimeSeries
		expect2      []*prompb.TimeSeries
	}{
		{
			desc:       "Use point time",
			pointToSet: point,
			expect1:    []*prompb.TimeSeries{promPoint},
			expect2:    []*prompb.TimeSeries{promPoint},
		}, {
			desc:         "Use current time, it is lagging behind last used timestamp",
			useCurrentTs: true,
			// use timestamp in future to simulate that now() is lagging
			lastTsUsed: futureTime,
			pointToSet: point,
			expect1:    []*prompb.TimeSeries{promPointInFuture1},
			expect2:    []*prompb.TimeSeries{promPointInFuture2},
		},
	}

	compareTSs := func(exp, got []*prompb.TimeSeries) bool {
		if len(exp) != len(got) {
			return false
		}
		for i, tsExp := range exp {
			tsGot := got[i]
			if !reflect.DeepEqual(tsExp.Labels, tsGot.Labels) {
				t.Errorf("labels missmatch; exp: %v; got %v", tsExp.Labels, tsGot.Labels)
				return false
			}
			if !reflect.DeepEqual(tsExp.Samples, tsGot.Samples) {
				t.Errorf("samples missmatch; exp: %v; got %v", tsExp.Samples, tsGot.Samples)
				return false
			}
		}
		return true
	}

	setPoint := func(p *data.Point, iter *timeSeriesIterator) []*prompb.TimeSeries {
		if err := iter.Set(p); err != nil {
			t.Error("could not set point:", err)
			return nil
		}
		var got []*prompb.TimeSeries
		for iter.HasNext() {
			got = append(got, iter.Next())
		}
		return got
	}
	for _, tc := range cases {
		t.Run(tc.desc, func(t *testing.T) {
			iter := &timeSeriesIterator{
				useCurrentTime: tc.useCurrentTs,
				lastTsUsed:     tc.lastTsUsed,
			}
			got1 := setPoint(tc.pointToSet, iter)
			got2 := setPoint(tc.pointToSet, iter)
			compareTSs(tc.expect1, got1)
			compareTSs(tc.expect2, got2)
		})
	}
}

package prometheus

import (
	"bufio"
	"bytes"
	"fmt"
	"sort"
	"testing"
	"time"

	"github.com/timescale/promscale/pkg/prompb"
	"github.com/timescale/tsbs/pkg/data"
	"github.com/timescale/tsbs/pkg/data/serialize"
)

func TestPrometheusSerializer(t *testing.T) {
	var buffer bytes.Buffer
	ser := Serializer{}
	err := ser.Serialize(serialize.TestPointDefault(), &buffer)
	if err != nil {
		t.Errorf("error while serializing point: %v", err)
	}
	promIter, err := NewPrometheusIterator(bufio.NewReader(&buffer))
	if err != nil {
		t.Errorf("error while creating iterator: %v", err)
	}

	series := make([]*prompb.TimeSeries, 0)

	for promIter.HasNext() {
		ts, err := promIter.Next()
		if err != nil {
			t.Errorf("error getting next: %v", err)
		}
		series = append(series, ts)
	}

	assertEqual(1, len(series), t, "Wrong number of series")

	ts := series[0]
	assertEqual(serialize.TestFloat, ts.Samples[0].GetValue(), t, "bad sample value")
	assertEqual(serialize.TestPointDefault().Timestamp().UnixNano()/1000000, ts.Samples[0].GetTimestamp(), t, "wrong timestamp")

	// We add metric name as label into TimeSeries
	assertEqual(len(serialize.TestPointDefault().TagKeys())+1, len(ts.Labels), t, "wrong number of tags")

	// Lets test point with multiple fields. We generate new TimeSeries for each field
	buffer.Reset()
	series = nil
	ser = Serializer{}
	err = ser.Serialize(serialize.TestPointMultiField(), &buffer)
	if err != nil {
		t.Errorf("error while serializing: %v", err)
	}

	promIter, err = NewPrometheusIterator(bufio.NewReader(&buffer))
	if err != nil {
		t.Errorf("error creating deserializer: %v", err)
	}

	for promIter.HasNext() {
		ts, err := promIter.Next()
		if err != nil {
			t.Errorf("error getting next protobuf: %v", err)
		}
		series = append(series, ts)
	}

	assertEqual(len(serialize.TestPointMultiField().FieldKeys()), len(series), t, "wrong number of series")
	assertEqual(len(serialize.TestPointMultiField().FieldKeys()), int(promIter.processed), t, "wrong iterator state")
	if series == nil {
		t.Errorf("expected series to != nil")
	} else {
		assertEqual(float64(serialize.TestInt64), series[0].Samples[0].GetValue(), t, "wrong sample value")
	}
}

func assertEqual(expected, got interface{}, t *testing.T, msg string) {
	if expected != got {
		t.Error(fmt.Sprintf("%s. Expected: %v, Got: %v", msg, expected, got))
	}
}

func TestConvertToPromSeries(t *testing.T) {
	someTimeAgo := time.Now().Add(-time.Second)
	oneFieldPoint := data.NewPoint()
	oneFieldPoint.SetTimestamp(&someTimeAgo)
	oneFieldPoint.AppendField([]byte("f"), 1)
	ofTS := prompb.TimeSeries{
		Labels:  []prompb.Label{{Name: "__name__", Value: "f"}},
		Samples: []prompb.Sample{{Value: 1, Timestamp: oneFieldPoint.Timestamp().UnixNano() / 1000000}},
	}

	twoFieldPoint := data.NewPoint()
	twoFieldPoint.SetTimestamp(&someTimeAgo)
	twoFieldPoint.AppendField([]byte("f"), 1)
	twoFieldPoint.AppendField([]byte("g"), 2)
	twoFieldPoint.AppendTag([]byte("b"), "t1")
	twoFieldPoint.AppendTag([]byte("a"), "t2")
	tfTS1 := prompb.TimeSeries{
		Labels:  []prompb.Label{{Name: "__name__", Value: "f"}, {Name: "a", Value: "t2"}, {Name: "b", Value: "t1"}},
		Samples: []prompb.Sample{{Value: 1, Timestamp: twoFieldPoint.Timestamp().UnixNano() / 1000000}},
	}
	tfTS2 := prompb.TimeSeries{
		Labels:  []prompb.Label{{Name: "__name__", Value: "g"}, {Name: "a", Value: "t2"}, {Name: "b", Value: "t1"}},
		Samples: []prompb.Sample{{Value: 2, Timestamp: twoFieldPoint.Timestamp().UnixNano() / 1000000}},
	}

	testCases := []struct {
		desc      string
		expError  bool
		inPoint   *data.Point
		inBuffer  []prompb.TimeSeries
		expBuffer []prompb.TimeSeries
	}{
		{desc: "Error on wrong size buffer", expError: true, inPoint: oneFieldPoint, inBuffer: []prompb.TimeSeries{}},
		{
			desc:      "Single field, single time-series",
			inPoint:   oneFieldPoint,
			inBuffer:  make([]prompb.TimeSeries, 1),
			expBuffer: []prompb.TimeSeries{ofTS},
		}, {
			desc:      "Two fields, two time-series, labels sorted",
			inPoint:   twoFieldPoint,
			inBuffer:  make([]prompb.TimeSeries, 2),
			expBuffer: []prompb.TimeSeries{tfTS1, tfTS2},
		},
	}

	for _, tc := range testCases {
		t.Run(tc.desc, func(t *testing.T) {
			err := convertToPromSeries(tc.inPoint, tc.inBuffer)
			if tc.expError && err != nil {
				return
			} else if tc.expError {
				t.Errorf("unexpected lack of error")
				return
			} else if err != nil {
				t.Errorf("unexpected error: %v", err)
				return
			}

			for i, ts := range tc.expBuffer {
				returnedTS := tc.inBuffer[i]
				if len(returnedTS.Samples) != len(ts.Samples) {
					t.Errorf("wrong samples size; exp: %d; got %d", len(returnedTS.Samples), len(ts.Samples))
					return
				}
				labelsAreSorted := sort.SliceIsSorted(returnedTS.Labels, func(i, j int) bool {
					return returnedTS.Labels[i].Name < returnedTS.Labels[j].Name
				})
				if !labelsAreSorted {
					t.Errorf("labels not sorted by name: %v", returnedTS.Labels)
				}
				for j, retLabel := range returnedTS.Labels {
					expLabel := tc.expBuffer[i].Labels[j]
					if expLabel.Name != retLabel.Name {
						t.Errorf("labels nor ordered; exp: %s; got %s", expLabel.Name, retLabel.Name)
					}
					if expLabel.Value != retLabel.Value {
						t.Errorf("label value missmatch; exp: %s; got %s", expLabel.Value, retLabel.Value)
					}
				}
				for j, retSample := range returnedTS.Samples {
					expSample := tc.expBuffer[i].Samples[j]
					if retSample.Value != expSample.Value {
						t.Errorf("sample value missmatch; exp: %f ; got: %f", expSample.Value, retSample.Value)
					}
					if retSample.Timestamp != expSample.Timestamp {
						t.Errorf("sample time missmatch; exp: %d; got: %d", expSample.Timestamp, retSample.Timestamp)
					}
				}
			}
		})
	}
}

package prometheus

import (
	"math/rand"
	"testing"

	"github.com/timescale/promscale/pkg/prompb"
	"github.com/timescale/tsbs/pkg/data"
)

func TestRandomPointIndexer(t *testing.T) {
	rand.Seed(0)
	var expected []uint
	pointsToIndex := 10
	numPartitions := 100
	for i := 0; i < pointsToIndex; i++ {
		expected = append(expected, uint(rand.Intn(numPartitions)))
	}
	rand.Seed(0)
	indexer := randomPointIndexer{numPartitions}
	for i := 0; i < pointsToIndex; i++ {
		index := indexer.GetIndex(data.LoadedPoint{})
		if index != expected[i] {
			t.Errorf("expected: %d, got: %d", expected[i], index)
		}
	}
}

func TestSeriesIDPointIndexer(t *testing.T) {
	oneLabel := []prompb.Label{{
		Name:  "l1",
		Value: "l1_v",
	}}
	twoLabels := []prompb.Label{{
		Name:  "l1",
		Value: "l1_v",
	}, {
		Name:  "l2",
		Value: "l2_v",
	}}

	var t1, t2 *prompb.TimeSeries
	pi := newSeriesIDPointIndexer(1000)

	t1 = &prompb.TimeSeries{
		Labels: oneLabel,
	}
	t2 = &prompb.TimeSeries{
		Labels: twoLabels,
	}

	t1Index := pi.GetIndex(data.NewLoadedPoint(t1))

	// test cache is properly filled
	piCasted := pi.(*seriesIDPointIndexer)
	t1CacheKey := nilDelimitedLabelsToStr(t1.Labels)
	cachedIndex, exists := piCasted.indexCache.Load(t1CacheKey)
	if !exists {
		t.Fatalf("cache not properly populated, val for %s is missing", t1CacheKey)
	}
	if cachedIndex.(uint) != t1Index {
		t.Fatalf("cache not properly populated, expected val %d, got %d", t1Index, cachedIndex.(int))
	}

	// test cache is used
	//// will change cached value, if changed value is returned, then it means
	//// the correct value is not calculated and stored
	modifiedIndex := cachedIndex.(uint) + 1
	piCasted.indexCache.Store(t1CacheKey, modifiedIndex)
	if modifiedIndex != pi.GetIndex(data.NewLoadedPoint(t1)) {
		t.Fatal("cached index value not used")
	}

	// test diff values for different label sets
	piCasted.indexCache.Delete(t1CacheKey)
	t1Index = piCasted.GetIndex(data.NewLoadedPoint(t1))
	t2Index := piCasted.GetIndex(data.NewLoadedPoint(t2))
	t2CacheKey := nilDelimitedLabelsToStr(t2.Labels)
	if cachedT2Index, exists := piCasted.indexCache.Load(t2CacheKey); !exists {
		t.Fatal("index of t2 not cached")
	} else if cachedT2Index != t2Index {
		t.Fatalf("for t2 cached index %d, returned %d", cachedT2Index, t2Index)
	}
	// for the selected label set and maxIndex indexes shouldn't be the same
	if t1Index == t2Index {
		t.Fatalf("two diff labelsets got same index")
	}
}

func TestNilDelimitedLabelsToStr(t *testing.T) {
	testCases := []struct {
		desc string
		in   []prompb.Label
		out  string
	}{
		{desc: "empty label set", in: []prompb.Label{}, out: ""},
		{
			desc: "one label",
			in: []prompb.Label{{
				Name:  "l1",
				Value: "l1_v",
			}},
			out: "l1\x00l1_v",
		}, {
			desc: "two labels",
			in: []prompb.Label{{
				Name:  "l1",
				Value: "l1_v",
			}, {
				Name:  "l2",
				Value: "l2_v",
			}},
			out: "l1\x00l1_v\x00\x00l2\x00l2_v",
		},
	}
	for _, tc := range testCases {
		t.Run(tc.desc, func(t *testing.T) {
			got := nilDelimitedLabelsToStr(tc.in)
			if got != tc.out {
				t.Errorf("expected: %s; got: %s", tc.out, got)
			}
		})
	}
}

package cassandra

import (
	"strings"
	"testing"
	"time"

	"github.com/timescale/tsbs/pkg/query"
)

func TestDevopsGetHostWhereWithHostnames(t *testing.T) {
	cases := []struct {
		desc      string
		hostnames []string
		want      []string
	}{
		{
			desc:      "single host",
			hostnames: []string{"foo1"},
			want:      []string{"hostname=foo1"},
		},
		{
			desc:      "multi host",
			hostnames: []string{"foo1", "foo2"},
			want:      []string{"hostname=foo1", "hostname=foo2"},
		},
	}

	for _, c := range cases {
		b := BaseGenerator{}
		d, err := b.NewDevops(time.Now(), time.Now(), 10)

		if err != nil {
			t.Fatalf("Error while creating devops generator")
		}

		got := d.(*Devops).getHostWhereWithHostnames(c.hostnames)
		if len(got) != len(c.want) {
			t.Errorf("%s: incorrect output len: got %d want %d", c.desc, len(got), len(c.want))
		}
		for i := range c.want {
			if got[i] != c.want[i] {
				t.Errorf("%s: incorrect output at %d: got %s want %s", c.desc, i, got[i], c.want[i])
			}
		}
	}
}

func TestDevopsFillInQuery(t *testing.T) {
	humanLabel := "this is my label"
	humanDesc := "and now my description"
	aggType := "sum"
	fields := []string{"foo1, foo2"}
	tags := [][]string{{"foo=val", "bar=val2"}}
	now := time.Now()

	b := BaseGenerator{}
	dq, err := b.NewDevops(now, now.Add(time.Nanosecond), 10)
	if err != nil {
		t.Fatalf("Error while creating devops generator")
	}
	d := dq.(*Devops)

	qi := d.GenerateEmptyQuery()
	q := qi.(*query.Cassandra)
	if len(q.HumanLabel) != 0 {
		t.Errorf("empty query has non-zero length human label")
	}
	if len(q.HumanDescription) != 0 {
		t.Errorf("empty query has non-zero length human desc")
	}
	if len(q.AggregationType) != 0 {
		t.Errorf("empty query has non-zero length agg type")
	}
	if len(q.MeasurementName) != 0 {
		t.Errorf("empty query has non-zero length measurement name")
	}
	if len(q.FieldName) != 0 {
		t.Errorf("empty query has non-zero length field name")
	}
	if len(q.TagSets) != 0 {
		t.Errorf("empty query has non-zero length tagset")
	}

	d.fillInQuery(q, humanLabel, humanDesc, aggType, fields, d.Interval, tags)

	if got := string(q.HumanLabel); got != humanLabel {
		t.Errorf("filled query mislabeled: got %s want %s", got, humanLabel)
	}
	if got := string(q.HumanDescription); got != humanDesc {
		t.Errorf("filled query mis-described: got %s want %s", got, humanDesc)
	}
	if got := string(q.AggregationType); got != aggType {
		t.Errorf("filled query has wrong agg type: got %s want %s", got, aggType)
	}
	if got := string(q.MeasurementName); got != "cpu" {
		t.Errorf("filled query has wrong measurement name: got %s want %s", got, "cpu")
	}
	if got := string(q.FieldName); got != strings.Join(fields, ",") {
		t.Errorf("filled query has wrong fields: got %s want %s", got, strings.Join(fields, ","))
	}
	if got := q.TimeStart.UnixNano(); got != now.UnixNano() {
		t.Errorf("filled query start time wrong: got %d want %d", got, now.UnixNano())
	}
	if got := q.TimeEnd.UnixNano(); got != now.UnixNano()+1 {
		t.Errorf("filled query end time wrong: got %d want %d", got, now.UnixNano()+1)
	}
	if got := len(q.TagSets); got != len(tags) {
		t.Errorf("filled query has wrong tagset length: got %d want %d", got, len(tags))
	}
	for i := range tags {
		if got := len(q.TagSets[i]); got != len(tags[i]) {
			t.Errorf("tag set len %d not equal: got %d want %d", i, got, len(tags[i]))
		}
		for j := range tags[i] {
			if got := q.TagSets[i][j]; got != tags[i][j] {
				t.Errorf("tag set at %d,%d incorrect: got %s want %s", i, j, got, tags[i][j])
			}
		}
	}
}

package devops

import (
	"github.com/timescale/tsbs/pkg/data"
	"math/rand"
	"testing"
	"time"
)

func TestPostgresqlMeasurementTick(t *testing.T) {
	now := time.Now()
	m := NewPostgresqlMeasurement(now)
